import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import Login from "./pages/auth/Login";
import Register from "./pages/auth/Register";
import ForgotPassword from "./pages/auth/ForgotPassword";
import ResetPassword from "./pages/auth/ResetPassword";
import Home from "./pages/Home";
import Scan from "./pages/Scan";
import Result from "./pages/Result";
import Deteccion from "./pages/Deteccion";
import Recomendacion from "./pages/Recomendacion";
import Geolocalizacion from "./pages/Geolocalizacion";
import Informes from "./pages/Informes";





function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<Navigate to="/login" />} />
        <Route path="/login" element={<Login />} />
        <Route path="/register" element={<Register />} />
        <Route path="/forgot-password" element={<ForgotPassword />} />
        <Route path="/reset-password/:token" element={<ResetPassword />} />
        <Route path="/home" element={<Home />} />
        <Route path="/scan" element={<Scan />} />
        <Route path="/result" element={<Result />} />
        <Route path="/result/:id" element={<Result />} />
        <Route path="/deteccion" element={<Deteccion />} />
        <Route path="/seguimiento" element={<Recomendacion />} />
        <Route path="/map" element={<Geolocalizacion />} />
        <Route path="/informes" element={<Informes />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
